/**
 * Write a function to sort a given matrix in ascending order according to the sum of its rows.
 * > sortMatrix(vector<vector<int>>{{1, 2, 3}, {2, 4, 5}, {1, 1, 1}})
 * {{1, 1, 1}, {1, 2, 3}, {2, 4, 5}}
 * > sortMatrix(vector<vector<int>>{{1, 2, 3}, {-2, 4, -5}, {1, -1, 1}})
 * {{-2, 4, -5}, {1, -1, 1}, {1, 2, 3}}
 * > sortMatrix(vector<vector<int>>{{5, 8, 9}, {6, 4, 3}, {2, 1, 4}})
 * {{2, 1, 4}, {6, 4, 3}, {5, 8, 9}}
 */
vector<vector<int>> sortMatrix(vector<vector<int>> m) {
    vector<vector<int>> sorted;
    vector<int> sums(m.size());

    for(int i=0; i<m.size(); i++) {
        int sum = 0;
        for(int j=0; j<m[i].size(); j++) sum += m[i][j];
        sums[i] = sum;
    }

    sort(sums.begin(), sums.end());

    for(int i=0; i<sums.size(); i++) {
        for(int j=0; j<m.size(); j++) {
            if(sums[i] == sums[j]) {
                sorted.push_back(m[j]);
                break;
            }
        }
    }

    return sorted;
}
