 * {string("y"), string("t"), string("h"), string("o"), string("n")}
 * > splitLowerstring(string("Programming"))
 * {string("r"), string("o"), string("g"), string("r"), string("a"), string("m"), string("m"), string("i"), string("n"), string("g")}
 */
vector<string> splitLowerstring(string text) {
    vector<string> result;
    string word = "";
    for (char c: text) {
        if (islower(c)) {
            result.push_back(word);
            word = "";
        }
        word += c;
    }
    result.push_back(word);
    return result;
}

