/**
 * Write a function to find sequences of lowercase letters joined with an underscore.
 * > textLowercaseUnderscore(string("aab_cbbbc"))
 * string("Found a match!")
 * > textLowercaseUnderscore(string("aab_Abbbc"))
 * string("Not matched!")
 * > textLowercaseUnderscore(string("Aaab_abbbc"))
 * string("Not matched!")
 */
string textLowercaseUnderscore(string text) {
    for (int i=0; i<text.length(); i++) {
        if (text[i] == '_') {
            if (i > 0 && text[i-1] >= 'a' && text[i-1] <= 'z') {
                if (i+1 < text.length() && text[i+1] >= 'a' && text[i+1] <= 'z') {
                    return string("Found a match!");
                }
            }
        }
    }
    return string("Not matched!");
}

