 * > func(vector<vector<int>>{{1, 2, 6}, {1, 3, 4, 5, 7, 8}, {1, 3, 5, 6, 8, 9}, {2, 5, 7, 11}, {1, 4, 7, 8, 12}}, 3)
 * {5, 7, 1}
 * > func(vector<vector<int>>{{1, 2, 6}, {1, 3, 4, 5, 7, 8}, {1, 3, 5, 6, 8, 9}, {2, 5, 7, 11}, {1, 4, 7, 8, 12}}, 1)
 * {1}
 * > func(vector<vector<int>>{{1, 2, 6}, {1, 3, 4, 5, 7, 8}, {1, 3, 5, 6, 8, 9}, {2, 5, 7, 11}, {1, 4, 7, 8, 12}}, 5)
 * {6, 5, 7, 8, 1}
 */
vector<int> func(vector<vector<int>> nums, int k) {
    if (nums.empty() || k <= 0) return {};
    vector<int> res;
    priority_queue<pair<int, int>> pq;
    for (auto& num : nums) {
        for (auto& n : num) {
            if (pq.empty() || pq.top().first < n) {
                pq.push({n, 1});
            } else if (pq.top().first == n) {
                pq.top().second++;
            }
            if (pq.size() > k) pq.pop();
        }
    }
    while (!pq.empty()) {
        res.push_back(pq.top().first);
        pq.pop();
    }
    return res;
}


