/**
 * Write a c++ function to convert a decimal number to binary number.
 * > decimalToBinary(10)
 * 1010
 * > decimalToBinary(1)
 * 1
 * > decimalToBinary(20)
 * 10100
 */
int decimalToBinary(int n) {
    if (n == 0) return 0;
    int binary = 0;
    int i = 1;
    while (n > 0) {
        int rem = n % 2;
        binary += rem * i;
        n /= 2;
        i *= 10;
    }
    return binary;
}


