/**
 * Write a function to check if the letters of a given string can be rearranged so that two characters that are adjacent to each other are different.
 * > rearangeString(string("aab"))
 * string("aba")
 * > rearangeString(string("aabb"))
 * string("abab")
 * > rearangeString(string("abccdd"))
 * string("cdabcd")
 */
string rearangeString(string s) {
    unordered_map<char, int> freq;
    for(char c: s) freq[c]++;

    priority_queue<pair<int, char>> pq;
    for(auto it: freq) pq.push({it.second, it.first});

    string res;
    while(!pq.empty()) {
        auto p = pq.top(); pq.pop();
        if(res.empty() || res.back() != p.second) {
            res += p.second;
            p.first--;
        }
        if(p.first > 0) pq.push(p);
    }

    return res;
}

