/**
 * Write a function to sort the given array by using counting sort.
 * > countingSort(vector<int>{1, 23, 4, 5, 6, 7, 8})
 * {1, 4, 5, 6, 7, 8, 23}
 * > countingSort(vector<int>{12, 9, 28, 33, 69, 45})
 * {9, 12, 28, 33, 45, 69}
 * > countingSort(vector<int>{8, 4, 14, 3, 2, 1})
 * {1, 2, 3, 4, 8, 14}
 */
vector<int> countingSort(vector<int> myList) {
    int max = *max_element(myList.begin(), myList.end());
    int min = *min_element(myList.begin(), myList.end());
    int range = max - min + 1;

    vector<int> count(range);
    vector<int> sorted(myList.size());

    for (int i = 0; i < myList.size(); i++) {
        count[myList[i] - min]++;
    }

    for (int i = 1; i < count.size(); i++) {
        count[i] += count[i-1];
    }

    for (int i = myList.size() - 1; i >= 0; i--) {
        sorted[count[myList[i] - min] - 1] = myList[i];
        count[myList[i] - min]--;
    }

    return sorted;
}

