 * > combSort(vector<int>{5, 15, 37, 25, 79})
 * {5, 15, 25, 37, 79}
 * > combSort(vector<int>{41, 32, 15, 19, 22})
 * {15, 19, 22, 32, 41}
 * > combSort(vector<int>{99, 15, 13, 47})
 * {13, 15, 47, 99}
 */
vector<int> combSort(vector<int> nums) {
    int n = nums.size();
    int gap = n;
    bool swapped = true;

    while (gap > 1 || swapped) {
        gap = max(1, int(gap/1.3));
        swapped = false;

        for (int i=0; i<n-gap; i++) {
            if (nums[i] > nums[i+gap]) {
                swap(nums[i], nums[i+gap]);
                swapped = true;
            }
        }
    }

    return nums;
}
