    int j = mid+1;
    int k = n-1;

    while(i >= 0 && j < n) {
        if(s[i] == s[j]) {
            i--;
            j++;
        } else {
            break;
        }
    }

    if(i < 0) {
        return num;
    }

    while(i >= 0 && s[i] == s[k]) {
        i--;
        k--;
    }

    int left = stoi(s.substr(0, i+1));
    int right = stoi(s.substr(j));

