 * false
 */
bool magicSquareTest(vector<vector<int>> myMatrix) {
    int n = myMatrix.size();
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += myMatrix[i][i];
    }

    for (int i = 0; i < n; i++) {
        int rowSum = 0;
        int colSum = 0;
        for (int j = 0; j < n; j++) {
            rowSum += myMatrix[i][j];
            colSum += myMatrix[j][i];
        }
        if (rowSum != sum || colSum != sum) return false;
    }

    int diagSum = 0;
    for (int i = 0; i < n; i++) {
        diagSum += myMatrix[i][i];
    }
    if (diagSum != sum) return false;

    diagSum = 0;
    for (int i = 0; i < n; i++) {
        diagSum += myMatrix[i][n-i-1];
    }
    if (diagSum != sum) return false;

    return true;
}
