 */
vector<int> pancakeSort(vector<int> nums) {
    int n = nums.size();
    for (int i=n-1; i>0; i--) {
        int max_idx = 0;
        for (int j=0; j<=i; j++) {
            if (nums[j] > nums[max_idx]) max_idx = j;
        }
        if (max_idx == i) continue;
        reverse(nums.begin(), nums.begin()+max_idx+1);
        reverse(nums.begin(), nums.begin()+i+1);
    }
    return nums;
}
