 * false
 * > isCoprime(25, 45)
 * false
 */
bool isCoprime(int x, int y) {
    if (x == 0 || y == 0) return false;
    if (x == 1 || y == 1) return true;

    int a = max(x, y);
    int b = min(x, y);

    while (b > 0) {
        int r = a % b;
        a = b;
        b = r;
    }

    return a == 1;
}

