/**
 * Write a c++ function to find k number of operations required to make all elements equal.
 * > minOps(vector<int>{2, 2, 2, 2}, 4, 3)
 * 0
 * > minOps(vector<int>{4, 2, 6, 8}, 4, 3)
 * -1
 * > minOps(vector<int>{21, 33, 9, 45, 63}, 5, 6)
 * 24
 */
int minOps(vector<int> arr, int n, int k) {
    int sum = 0;
    for (int i=0; i<n; i++) sum += arr[i];
    if (sum%n != 0) return -1;
    int avg = sum/n;
    int ops = 0;
    for (int i=0; i<n; i++) {
        int diff = abs(arr[i] - avg);
        if (diff%k != 0) return -1;
        ops += diff/k;
    }
    return ops;
}
