/**
 * Write a function to verify validity of a string of parentheses.
 * > isValidParenthese(string("(){}[]"))
 * true
 * > isValidParenthese(string("()[{)}"))
 * false
 * > isValidParenthese(string("()"))
 * true
 */
bool isValidParenthese(string str1) {
    stack<char> s;
    for (char c : str1) {
        if (c == '(' || c == '{' || c == '[') {
            s.push(c);
        } else {
            if (s.empty()) return false;
            char c1 = s.top();
            s.pop();
            if (c == ')' && c1 != '(') return false;
            if (c == '}' && c1 != '{') return false;
            if (c == ']' && c1 != '[') return false;
        }
    }
    return s.empty();
}


