 */
string commonPrefix(vector<string> arr, int n) {
    if (n == 0) return "";
    if (n == 1) return arr[0];

    string prefix = arr[0];
    for (int i=1; i<n; i++) {
        string word = arr[i];
        int j = 0;
        for (; j<prefix.length() && j<word.length(); j++) {
            if (prefix[j] != word[j]) break;
        }
        prefix = prefix.substr(0, j);
    }

    return prefix;
}

