/**
 * Write a function to find the longest common subsequence for the given two sequences.
 * > longestCommonSubsequence(string("AGGTAB"), string("GXTXAYB"), 6, 7)
 * 4
 * > longestCommonSubsequence(string("ABCDGH"), string("AEDFHR"), 6, 6)
 * 3
 * > longestCommonSubsequence(string("AXYT"), string("AYZX"), 4, 4)
 * 2
 */
int longestCommonSubsequence(string x, string y, int m, int n) {
    int dp[m+1][n+1];
    for (int i=0; i<=m; i++) dp[i][0] = 0;
    for (int j=0; j<=n; j++) dp[0][j] = 0;

    for (int i=1; i<=m; i++) {
        for (int j=1; j<=n; j++) {
            if (x[i-1] == y[j-1]) dp[i][j] = 1 + dp[i-1][j-1];
            else dp[i][j] = max(dp[i-1][j], dp[i][j-1]);
        }
    }

    return dp[m][n];
}

