 * true
 */
bool prodSquare(int n) {
    int sqrtN = sqrt(n);
    for (int i=1; i<=sqrtN; i++) {
        if (sqrtN % i == 0) {
            int a = i;
            int b = sqrtN / i;
            if (a*a + b*b == n) return true;
        }
    }
    return false;
}

