/**
 * Write a c++ function to convert octal number to decimal number.
 * > octalToDecimal(25)
 * 21
 * > octalToDecimal(30)
 * 24
 * > octalToDecimal(40)
 * 32
 */
int octalToDecimal(int n) {
    int decimal = 0;
    int base = 1;

    while (n > 0) {
        int lastDigit = n % 10;
        decimal += lastDigit * base;
        n /= 10;
        base *= 8;
    }

    return decimal;
}


