/**
 * Write a c++ function to find the first position of an element in a sorted array.
 * > first(vector<int>{1, 2, 3, 4, 5, 6, 6}, 6, 6)
 * 5
 * > first(vector<int>{1, 2, 2, 2, 3, 2, 2, 4, 2}, 2, 9)
 * 1
 * > first(vector<int>{1, 2, 3}, 1, 3)
 * 0
 */
int first(vector<int> arr, int x, int n) {
    int l = 0, r = n-1;
    int mid;

    while (l <= r) {
        mid = (l+r)/2;

        if (arr[mid] == x) {
            if (mid == 0 || arr[mid-1] != x) return mid;
            else r = mid-1;
        } else if (arr[mid] < x) {
            l = mid+1;
        } else {
            r = mid-1;
        }
    }

    return -1;
}

