 * > hammingDistance(4, 8)
 * 2
 * > hammingDistance(2, 4)
 * 2
 * > hammingDistance(1, 2)
 * 2
 */
int hammingDistance(int n1, int n2) {
    int count = 0;
    int xor_val = n1 ^ n2;

    while (xor_val) {
        if (xor_val & 1) count++;
        xor_val >>= 1;
    }

    return count;
}

