/**
 * Write a function to count the longest repeating subsequences such that the two subsequences don’t have same string characters at same positions.
 * > findLongestRepeatingSubseq(string("AABEBCDD"))
 * 3
 * > findLongestRepeatingSubseq(string("aabb"))
 * 2
 * > findLongestRepeatingSubseq(string("aab"))
 * 1
 */
int findLongestRepeatingSubseq(string str) {
    int n = str.length();
    int dp[n+1][n+1];
    memset(dp, 0, sizeof(dp));

    for (int i=1; i<=n; i++) {
        for (int j=1; j<=n; j++) {
            if (str[i-1] == str[j-1] && i != j) {
                dp[i][j] = 1 + dp[i-1][j-1];
            } else {
                dp[i][j] = max(dp[i-1][j], dp[i][j-1]);
            }
        }
    }

    return dp[n][n];
}
