 * > heapReplace(vector<int>{25, 44, 68, 21, 39, 23, 89}, 500)
 * {23, 25, 68, 44, 39, 500, 89}
 */
vector<int> heapReplace(vector<int> heap, int a) {
    int n = heap.size();
    int i = 0;
    while(i < n && heap[i] < a) i = 2*i+1;
    if(i < n) heap[i] = a;
    else heap.push_back(a);
    return heap;
}

