/**
 * Write a function to extract maximum and minimum k elements in the given tuple.
 * > extractMinMax(vector<int>{5, 20, 3, 7, 6, 8}, 2)
 * {3, 5, 8, 20}
 * > extractMinMax(vector<int>{4, 5, 6, 1, 2, 7}, 3)
 * {1, 2, 4, 5, 6, 7}
 * > extractMinMax(vector<int>{2, 3, 4, 8, 9, 11, 7}, 4)
 * {2, 3, 4, 7, 8, 9, 11}
 */
vector<int> extractMinMax(vector<int> testTup, int k) {
    vector<int> result;
    priority_queue<int> maxHeap;
    priority_queue<int, vector<int>, greater<int>> minHeap;

    for (int i=0; i<testTup.size(); i++) {
        if (maxHeap.size() < k) {
            maxHeap.push(testTup[i]);
            minHeap.push(testTup[i]);
        } else {
            if (testTup[i] > maxHeap.top()) {
                maxHeap.pop();
                maxHeap.push(testTup[i]);
            }
            if (testTup[i] < minHeap.top()) {
                minHeap.pop();
                minHeap.push(testTup[i]);
            }
        }
    }

    while (!maxHeap.empty()) {
        result.push_back(maxHeap.top());
        maxHeap.pop();
    }

    while (!minHeap.empty()) {
        result.push_back(minHeap.top());
        minHeap.pop();
    }

    return result;
}

