/**
 * Write a c++ function to find the minimum element in a sorted and rotated array.
 * > findMin(vector<int>{1, 2, 3, 4, 5}, 0, 4)
 * 1
 * > findMin(vector<int>{4, 6, 8}, 0, 2)
 * 4
 * > findMin(vector<int>{2, 3, 5, 7, 9}, 0, 4)
 * 2
 */
int findMin(vector<int> arr, int low, int high) {
    if (low == high) return arr[low];

    int mid = (low + high) / 2;

    if (mid < high && arr[mid] > arr[mid + 1]) return arr[mid + 1];
    if (mid > low && arr[mid - 1] > arr[mid]) return arr[mid];

    if (arr[high] > arr[mid]) return findMin(arr, low, mid - 1);
    return findMin(arr, mid + 1, high);
}


