 * 15
 * > maxSum(vector<vector<int>>{{2}, {3, 2}, {13, 23, 12}}, 3)
 * 28
 */
int maxSum(vector<vector<int>> tri, int n) {
    for (int i=n-2; i>=0; i--) {
        for (int j=0; j<=i; j++) {
            tri[i][j] += max(tri[i+1][j], tri[i+1][j+1]);
