 * 3.162277660168379
 * > babylonianSquareroot(2)
 * 1.414213562373095
 * > babylonianSquareroot(9)
 * 3.0
 */
double babylonianSquareroot(int number) {
    double guess = 1;
    double epsilon = 0.000000000000001;

    while(abs(guess*guess - number) > epsilon) {
        guess = (guess + number/guess) / 2;
    }

    return guess;
