 * 7
 * > lps(string("PART OF THE JOURNEY IS PART"))
 * 9
 */
int lps(string str) {
    int n = str.length();
    int dp[n+1][n+1];

    for (int i=0; i<=n; i++) {
        for (int j=0; j<=n; j++) {
            if (i == 0 || j == 0)
                dp[i][j] = 0;
            else if (str[i-1] == str[j-1])
                dp[i][j] = 1 + dp[i-1][j-1];
            else
