 * > countNoOfWays(2, 4)
 * 16
 * > countNoOfWays(3, 2)
 * 6
 * > countNoOfWays(4, 4)
 * 228
 */
int countNoOfWays(int n, int k) {
    if(n == 0) return 0;
    if(n == 1) return k;
    if(n == 2) return k*k;
    if(n == 3) return k*k*k;

    int dp[n+1][k+1];
    memset(dp, 0, sizeof(dp));

    for(int i=0;i<k;i++) {
        dp[1][i] = 1;
    }

    for(int i=2;i<=n;i++) {
        for(int j=0;j<k;j++) {
            for(int l=0;l<k;l++) {
                if(j == l) {
                    dp[i][j] += dp[i-1][l];
                } else {
                    dp[i][j] += dp[i-2][l];
                }
            }
        }
    }

    int sum = 0;
    for(int i=0;i<k;i++) {
        sum += dp[n][i];
    }

    return sum;
}

