 * > findElement(vector<int>{1, 2, 3, 4, 5}, vector<vector<int>>{{0, 2}, {0, 3}}, 2, 1)
 * 3
 * > findElement(vector<int>{1, 2, 3, 4}, vector<vector<int>>{{0, 1}, {0, 2}}, 1, 2)
 * 3
 * > findElement(vector<int>{1, 2, 3, 4, 5, 6}, vector<vector<int>>{{0, 1}, {0, 2}}, 1, 1)
 * 1
 */
int findElement(vector<int> arr, vector<vector<int>> ranges, int rotations, int index) {
    int n = arr.size();
    int start = 0, end = n-1;
    int mid = 0;
    int rotation = 0;

    while(start <= end) {
        mid = start + (end-start)/2;
        if(arr[mid] == index) return arr[mid];
        if(arr[mid] < index) start = mid+1;
        else end = mid-1;
    }

    for(int i=0; i<ranges.size(); i++) {
        if(ranges[i][0] <= mid && mid <= ranges[i][1]) {
            rotation = ranges[i][1] - mid + 1;
            break;
        }
    }

    int newIndex = (index + rotation) % n;
    return findElement(arr, ranges, rotations, newIndex);
}

