 */
vector<int> largeProduct(vector<int> nums1, vector<int> nums2, int n) {
    vector<int> res;
    priority_queue<int> pq;

    for(int i : nums1) {
        for(int j : nums2) {
            pq.push(i*j);
            if(pq.size() > n) pq.pop();
        }
    }

    while(!pq.empty()) {
