 * > getMinSquares(6)
 * 3
 * > getMinSquares(2)
 * 2
 * > getMinSquares(4)
 * 1
 */
int getMinSquares(int n) {
    int dp[n+1];
    dp[0] = 0;
    dp[1] = 1;

    for (int i=2; i<=n; i++) {
        dp[i] = i;
        for (int j=1; j*j<=i; j++) {
            dp[i] = min(dp[i], 1+dp[i-j*j]);
        }
    }

    return dp[n];
}

