    if (text.length() == 1) return "Found a match!";

    int i = text.length() - 1;
    while (i >= 0) {
        if (text[i] == ' ') {
            i--;
            continue;
        }
        if (text[i] == '.' || text[i] == '!' || text[i] == '?') {
            i--;
            continue;
        }
        if (text[i] == ' ') {
            return "Found a match!";
        }
        return "Not matched!";
    }
    return "Not matched!";
}

