 * > findMinimumRange(vector<vector<int>>{{3, 6, 8, 10, 15}, {1, 5, 12}, {4, 8, 15, 16}, {2, 6}})
 * {4, 6}
 * > findMinimumRange(vector<vector<int>>{{2, 3, 4, 8, 10, 15}, {1, 5, 12}, {7, 8, 15, 16}, {3, 6}})
 * {4, 7}
 * > findMinimumRange(vector<vector<int>>{{4, 7, 9, 11, 16}, {2, 6, 13}, {5, 9, 16, 17}, {3, 7}})
 * {5, 7}
 */
vector<int> findMinimumRange(vector<vector<int>> list) {
    int n = list.size();
    vector<int> ans = {INT_MAX, INT_MIN};

    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;

    for(int i=0; i<n; i++) {
        pq.push({list[i][0], i});
    }

    while(pq.size() == n) {
        auto top = pq.top();
        pq.pop();

        int val = top.first;
        int idx = top.second;

        if(val < ans[0]) ans[0] = val;
        if(val > ans[1]) ans[1] = val;

        if(list[idx].size() > 1) {
            pq.push({list[idx][1], idx});
            list[idx].erase(list[idx].begin());
        }
    }

    return ans;
}
