 * > moddivList(vector<int>{4, 5, 6}, vector<int>{1, 2, 3})
 * {0, 1, 0}
 * > moddivList(vector<int>{3, 2}, vector<int>{1, 4})
 * {0, 2}
 * > moddivList(vector<int>{90, 120}, vector<int>{50, 70})
 * {40, 50}
 */
vector<int> moddivList(vector<int> nums1, vector<int> nums2) {
    map<int, int> m;
    for (int i : nums2) m[i]++;
    vector<int> res;
    for (int i : nums1) {
        if (m.find(i) != m.end()) {
            res.push_back(0);
            m[i]--;
        } else {
            int x = i;
            for (auto it = m.begin(); it != m.end(); it++) {
                if (it->first > x) break;
                if (it->second > 0) {
                    res.push_back(x/it->first);
                    x = x%it->first;
                    m[it->first]--;
                    break;
                }
            }
        }
    }
    return res;
}

