/**
 * Write a function to compute the value of ncr%p.
 * > ncrModp(10, 2, 13)
 * 6
 * > ncrModp(15, 12, 43)
 * 25
 * > ncrModp(17, 9, 18)
 * 10
 */
int ncrModp(int n, int r, int p) {
    if (r > n) return 0;
    if (r == 0 || r == n) return 1;

    int dp[r+1];
    dp[0] = 1;
    for (int i=1; i<=r; i++) {
        dp[i] = (dp[i-1]*(n-i+1))%p;
        dp[i] = (dp[i]*inverse(i, p))%p;
    }

    return dp[r];
}
