 * > kSmallestPairs(vector<int>{1, 3, 7}, vector<int>{2, 4, 6}, 2)
 * {{1, 2}, {1, 4}}
 * > kSmallestPairs(vector<int>{1, 3, 7}, vector<int>{2, 4, 6}, 1)
 * {{1, 2}}
 * > kSmallestPairs(vector<int>{1, 3, 7}, vector<int>{2, 4, 6}, 7)
 * {{1, 2}, {1, 4}, {3, 2}, {1, 6}, {3, 4}, {3, 6}, {7, 2}}
 */
vector<vector<int>> kSmallestPairs(vector<int> nums1, vector<int> nums2, int k) {
    vector<vector<int>> result;
    if(nums1.empty() || nums2.empty() || k <= 0) return result;

    priority_queue<pair<int, pair<int, int>>, vector<pair<int, pair<int, int>>>, greater<pair<int, pair<int, int>>>> pq;
    for(int i=0; i<nums1.size(); i++) {
        for(int j=0; j<nums2.size(); j++) {
            pq.push({nums1[i] + nums2[j], {nums1[i], nums2[j]}});
            if(pq.size() > k) pq.pop();
        }
    }

    while(!pq.empty()) {
        result.push_back({pq.top().second.first, pq.top().second.second});
        pq.pop();
    }

    return result;
}
