 * 7
 * > maxProfit(vector<int>{10, 6, 8, 4, 2}, 2)
 * 2
 */
int maxProfit(vector<int> price, int k) {
    int n = price.size();
    if(n == 0) return 0;
    if(k >= n/2) {
        int profit = 0;
        for(int i=1; i<n; i++) {
            if(price[i] > price[i-1])
                profit += price[i] - price[i-1];
        }
        return profit;
    }

    vector<vector<int>> dp(n, vector<int>(k+1, 0));
    for(int i=1; i<n; i++) {
        int diff = price[i] - price[i-1];
        for(int j=1; j<=k; j++) {
            dp[i][j] = max(dp[i-1][j], dp[i-1][j-1] + max(diff, 0));
        }
    }

    return dp[n-1][k];
}
