 * {14, 22}
 * > heapQueueSmallest(vector<int>{25, 35, 22, 85, 14, 65, 75, 22, 58}, 5)
 * {14, 22, 22, 25, 35}
 */
vector<int> heapQueueSmallest(vector<int> nums, int n) {
    if (n > nums.size()) return {};
    priority_queue<int, vector<int>, greater<int>> pq;
    for (int i=0; i<n; i++) pq.push(nums[i]);
    for (int i=n; i<nums.size(); i++) {
        if (nums[i] < pq.top()) {
            pq.pop();
            pq.push(nums[i]);
        }
    }
    vector<int> result;
    while (!pq.empty()) {
        result.push_back(pq.top());
        pq.pop();
    }
    return result;
}
