/**
 * Write a function to find the square root of a perfect number.
 * > sqrtRoot(4)
 * 2
 * > sqrtRoot(16)
 * 4
 * > sqrtRoot(400)
 * 20
 */
int sqrtRoot(int num) {
    int low = 1, high = num;
    int mid = 0;

    while(low <= high) {
        mid = (low + high) / 2;

        if(mid * mid == num)
            return mid;
        else if(mid * mid < num)
            low = mid + 1;
        else
            high = mid - 1;
    }

    return mid;
}
