 * > findMax(vector<int>{2, 3, 5, 6, 9}, 0, 4)
 * 9
 * > findMax(vector<int>{3, 4, 5, 2, 1}, 0, 4)
 * 5
 * > findMax(vector<int>{1, 2, 3}, 0, 2)
 * 3
 */
int findMax(vector<int> arr, int low, int high) {
    if (low == high) return arr[low];
    if (low+1 == high) return max(arr[low], arr[high]);

    int mid = (low+high)/2;
    if (arr[mid] > arr[mid+1]) return arr[mid];
    else if (arr[mid] < arr[mid+1]) return findMax(arr, mid+1, high);
    else return findMax(arr, low, mid);
}


