/**
 * Write a c++ function to check whether a given sequence is linear or not.
 * > seqLinear(vector<int>{0, 2, 4, 6, 8, 10})
 * string("Linear Sequence")
 * > seqLinear(vector<int>{1, 2, 3})
 * string("Linear Sequence")
 * > seqLinear(vector<int>{1, 5, 2})
 * string("Non Linear Sequence")
 */
string seqLinear(vector<int> seqNums) {
    int diff = seqNums[1] - seqNums[0];
    for (int i=2; i<seqNums.size(); i++) {
        if (seqNums[i] - seqNums[i-1] != diff) return "Non Linear Sequence";
    }
    return "Linear Sequence";
}


