 * > tupleToFloat(vector<int>{4, 56})
 * 4.56
 * > tupleToFloat(vector<int>{7, 256})
 * 7.256
 * > tupleToFloat(vector<int>{8, 123})
 * 8.123
 */
double tupleToFloat(vector<int> testTup) {
    double result = 0;
    int n = testTup.size();
    for (int i=0; i<n; i++) {
        result += testTup[i] * pow(10, n-i-1);
    }
    return result;
}
