/**
 * Write a c++ function to find the difference between sum of cubes of first n natural numbers and the sum of first n natural numbers.
 * > difference(3)
 * 30
 * > difference(5)
 * 210
 * > difference(2)
 * 6
 */
int difference(int n) {
    int sum_of_cubes = 0;
    int sum = 0;

    for(int i=1; i<=n; i++) {
        sum_of_cubes += i*i*i;
        sum += i;
    }

    return sum_of_cubes - sum*sum;
}
