/**
 * Write a c++ function to count the pairs with xor as an odd number.
 * > findOddPair(vector<int>{5, 4, 7, 2, 1}, 5)
 * 6
 * > findOddPair(vector<int>{7, 2, 8, 1, 0, 5, 11}, 7)
 * 12
 * > findOddPair(vector<int>{1, 2, 3}, 3)
 * 2
 */
int findOddPair(vector<int> a, int n) {
    int count = 0;
    for (int i=0; i<n; i++) {
        for (int j=i+1; j<n; j++) {
            if ((a[i] ^ a[j]) & 1) count++;
        }
    }
    return count;
}

