/**
 * Write a c++ function to find the digit distance between two integers.
 * > digitDistanceNums(1, 2)
 * 1
 * > digitDistanceNums(23, 56)
 * 6
 * > digitDistanceNums(123, 256)
 * 7
 */
int digitDistanceNums(int n1, int n2) {
    int distance = 0;
    while (n1 != 0 || n2 != 0) {
        int d1 = n1 % 10;
        int d2 = n2 % 10;
        n1 /= 10;
        n2 /= 10;
        distance += abs(d1 - d2);
    }
    return distance;
}
