/**
 * Write a function to find the largest sum of contiguous subarray in the given array.
 * > maxSubArraySum(vector<int>{-2, -3, 4, -1, -2, 1, 5, -3}, 8)
 * 7
 * > maxSubArraySum(vector<int>{-3, -4, 5, -2, -3, 2, 6, -4}, 8)
 * 8
 * > maxSubArraySum(vector<int>{-4, -5, 6, -3, -4, 3, 7, -5}, 8)
 * 10
 */
int maxSubArraySum(vector<int> a, int size) {
    int max_sum = INT_MIN, sum = 0;

    for (int i=0; i<size; i++) {
        sum += a[i];
        if (sum > max_sum) max_sum = sum;
        if (sum < 0) sum = 0;
    }

    return max_sum;
}

