/**
 * Write a c++ function to find the maximum length of sublist.
 * > findMaxLength(vector<vector<int>>{{1}, {1, 4}, {5, 6, 7, 8}})
 * 4
 * > findMaxLength(vector<vector<int>>{{0, 1}, {2, 2}, {3, 2, 1}})
 * 3
 * > findMaxLength(vector<vector<int>>{{7}, {22, 23}, {13, 14, 15}, {10, 20, 30, 40, 50}})
 * 5
 */
int findMaxLength(vector<vector<int>> lst) {
    int max_len = 0;
    for (int i=0; i<lst.size(); ++i) {
        int len = 0;
        for (int j=i; j<lst.size(); ++j) {
            len += lst[j].size();
            max_len = max(max_len, len);
        }
    }
    return max_len;
}

