/**
 * Write a function to extract values between quotation marks of a string.
 * > extractValues(string("\"Python\", \"PHP\", \"Java\""))
 * {string("Python"), string("PHP"), string("Java")}
 * > extractValues(string("\"python\",\"program\",\"language\""))
 * {string("python"), string("program"), string("language")}
 * > extractValues(string("\"red\",\"blue\",\"green\",\"yellow\""))
 * {string("red"), string("blue"), string("green"), string("yellow")}
 */
vector<string> extractValues(string text) {
    vector<string> values;
    string value = "";
    bool isQuote = false;
    for (char c: text) {
        if (c == '"') {
            if (isQuote) {
                values.push_back(value);
                value = "";
            }
            isQuote = !isQuote;
        } else if (isQuote) {
            value += c;
        }
    }
    return values;
}
