/**
 * Write a function to find maximum possible sum of disjoint pairs for the given array of integers and a number k.
 * > maxSumPairDiffLessthanK(vector<int>{3, 5, 10, 15, 17, 12, 9}, 7, 4)
 * 62
 * > maxSumPairDiffLessthanK(vector<int>{5, 15, 10, 300}, 4, 12)
 * 25
 * > maxSumPairDiffLessthanK(vector<int>{1, 2, 3, 4, 5, 6}, 6, 6)
 * 21
 */
int maxSumPairDiffLessthanK(vector<int> arr, int n, int k) {
    sort(arr.begin(), arr.end());
    int i = 0, j = n-1, sum = 0;
    while(i < j) {
        if(arr[i] + arr[j] < k) {
            sum += arr[i] + arr[j];
            i++;
            j--;
        } else {
            j--;
        }
    }
    return sum;
}
