/**
 * Write a c++ function to calculate the product of the unique numbers of a given list.
 * > uniqueProduct(vector<int>{10, 20, 30, 40, 20, 50, 60, 40})
 * 720000000
 * > uniqueProduct(vector<int>{1, 2, 3, 1})
 * 6
 * > uniqueProduct(vector<int>{7, 8, 9, 0, 1, 1})
 * 0
 */
int uniqueProduct(vector<int> listData) {
    int product = 1;
    unordered_set<int> unique;

    for (int data : listData) {
        if (unique.find(data) == unique.end()) {
            unique.insert(data);
            product *= data;
        }
    }

    return product;
}

