/**
 * Write a c++ function to check whether an array is subarray of another or not.
 * > isSubArray(vector<int>{1, 4, 3, 5}, vector<int>{1, 2}, 4, 2)
 * false
 * > isSubArray(vector<int>{1, 2, 1}, vector<int>{1, 2, 1}, 3, 3)
 * true
 * > isSubArray(vector<int>{1, 0, 2, 2}, vector<int>{2, 2, 0}, 4, 3)
 * false
 */
bool isSubArray(vector<int> a, vector<int> b, int n, int m) {
    if (m > n) return false;
    int i = 0, j = 0;
    while (i < n && j < m) {
        if (a[i] == b[j]) {
            i++;
            j++;
        } else {
            i++;
        }
    }
    return j == m;
}


