/**
 * Write a c++ function to find the last digit in factorial of a given number.
 * > lastDigitFactorial(4)
 * 4
 * > lastDigitFactorial(21)
 * 0
 * > lastDigitFactorial(30)
 * 0
 */
int lastDigitFactorial(int n) {
    if (n < 0) return -1;
    if (n == 0) return 1;

    int lastDigit = 1;
    for (int i=2; i<=n; i++) {
        lastDigit *= i;
        lastDigit %= 10;
    }

    return lastDigit;
}

