    for (int i=0; i<testTup1.size(); i++) {
        if (find(testTup2.begin(), testTup2.end(), testTup1[i]) == testTup2.end())
            result.push_back(testTup1[i]);
    }
    for (int i=0; i<testTup2.size(); i++) {
        if (find(testTup1.begin(), testTup1.end(), testTup2[i]) == testTup1.end())
            result.push_back(testTup2[i]);
    }
    return result;
